431	@@ -0,0 +1,94 @@
432	+import { CurrencyPipe } from '@angular/common';
433	+import { Component, OnInit, computed, inject, signal } from '@angular/core';
434	+import { RouterLink } from '@angular/router';
435	+import { forkJoin } from 'rxjs';
436	+
437	+import { ProductService } from '../../core/services/product.service';
438	+import { CartService } from './cart.service';
439	+
440	+interface CartLine {
441	+  productId: string;
442	+  supplierId: string;
443	+  productName: string;
444	+  supplierName: string;
445	+  price: number;
446	+  quantity: number;
447	+}
448	+
449	+@Component({
450	+  selector: 'app-cart',
451	+  imports: [CurrencyPipe, RouterLink],
452	+  templateUrl: './cart.html',
453	+  styleUrl: './cart.scss'
454	+})
455	+export class Cart implements OnInit {
456	+  private readonly cartService = inject(CartService);
457	+  private readonly productService = inject(ProductService);
458	+
459	+  readonly lines = signal<CartLine[]>([]);
460	+  readonly loading = signal(true);
461	+  readonly error = signal(false);
462	+
463	+  readonly total = computed(() => this.lines().reduce((sum, line) => sum + line.price * line.quantity, 0));
464	+
465	+  ngOnInit(): void {
466	+    this.load();
467	+  }
468	+
469	+  private load(): void {
470	+    const items = this.cartService.items();
471	+    if (items.length === 0) {
472	+      this.lines.set([]);
473	+      this.loading.set(false);
474	+      this.error.set(false);
475	+      return;
476	+    }
477	+    this.loading.set(true);
478	+    this.error.set(false);
479	+    const distinctProductIds = [...new Set(items.map((item) => item.productId))];
480	+    forkJoin(distinctProductIds.map((id) => this.productService.getProduct(id))).subscribe({
481	+      next: (products) => {
482	+        const productsById = new Map(products.map((product) => [product.id, product]));
483	+        this.lines.set(
484	+          items.map((item) => {
485	+            const product = productsById.get(item.productId)!;
486	+            const offer = product.offers.find((o) => o.supplierId === item.supplierId)!;
487	+            return {
488	+              productId: item.productId,
489	+              supplierId: item.supplierId,
490	+              productName: product.name,
491	+              supplierName: offer.supplierName,
492	+              price: offer.price,
493	+              quantity: item.quantity
494	+            };
495	+          })
496	+        );
497	+        this.loading.set(false);
498	+      },
499	+      error: () => {
500	+        this.loading.set(false);
501	+        this.error.set(true);
502	+      }
503	+    });
504	+  }
505	+
506	+  onQuantityChange(productId: string, supplierId: string, event: Event): void {
507	+    const input = event.target as HTMLInputElement;
508	+    const raw = Number(input.value);
509	+    const clamped = Number.isInteger(raw) && raw >= 1 ? raw : 1;
510	+    input.value = String(clamped);
511	+    this.cartService.updateQuantity(productId, supplierId, clamped);
512	+    this.lines.set(
513	+      this.lines().map((line) =>
514	+        line.productId === productId && line.supplierId === supplierId ? { ...line, quantity: clamped } : line
515	+      )
516	+    );
517	+  }
518	+
519	+  onRemove(productId: string, supplierId: string): void {
520	+    this.cartService.removeItem(productId, supplierId);
521	+    this.lines.set(
522	+      this.lines().filter((line) => !(line.productId === productId && line.supplierId === supplierId))
523	+    );
524	+  }
525	+}
